SHEET_DATA_VEDIC["Данные"].literals["A195"] = 2;
SHEET_DATA_VEDIC["Данные"].literals["B195"] = "Эмоцияның бақылаудан шығуына жол бермей, жақсы араласып, қамқорлық жасап, отбасымен көбірек уақыт өткізу керек.";
SHEET_DATA_VEDIC["Данные"].literals["A196"] = 3;
