SHEET_DATA_VEDIC["Данные"].literals["A197"] = 4;
SHEET_DATA_VEDIC["Данные"].literals["B197"] = "Рухани тәжірибеге, шетелге сапарға қолайлы ай, салауатты өмір салтын кез келген түрде бастаған немесе жалғастырған жақсы.";
SHEET_DATA_VEDIC["Данные"].literals["A198"] = 5;
SHEET_DATA_VEDIC["Данные"].literals["B198"] = "Жаңа мүмкіндіктерге немесе өзгерістерге, саяхатқа, сапарға, таныстыққа, бір нәрсені үйренуге жақсы ай, бірақ ретсіздік пен әбігерден аулақ болу керек.";
SHEET_DATA_VEDIC["Данные"].literals["A199"] = 6;
SHEET_DATA_VEDIC["Данные"].literals["B199"] = "Үй шаруасымен, шығармашылықпен, әдемі нәрселермен айналысып, өзіңізді махаббат пен қарым-қатынасқа көбірек арнаған жақсы.";
SHEET_DATA_VEDIC["Данные"].literals["A200"] = 7;
SHEET_DATA_VEDIC["Данные"].literals["B200"] = "Ай оңашалануға, өзін-өзі талдауға бойлауға мүмкіндік береді, өзіңізге жұмыс жүгін артпаған дұрыс, бірақ күрделі пәндерді, эзотериканы зерттеуге болады.";
SHEET_DATA_VEDIC["Данные"].literals["A201"] = 8;
